// src/components/AdminMessages/AdminMessages.jsx
import { useState, useEffect } from 'react';
import { Search, Send, Paperclip, Smile, MoreVertical } from 'lucide-react';
import { chatService } from '../services/chatService';
import ConversationList from './ConversationList';
import ChatArea from './ChatArea';

const AdminMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadConversations();
  }, []);

  const loadConversations = async () => {
    try {
      const token = localStorage.getItem('token');
      const data = await chatService.getConversations(token);
      setConversations(data);
    } catch (error) {
      console.error('Erreur chargement conversations:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadMessages = async (conversationId) => {
    try {
      const token = localStorage.getItem('token');
      const data = await chatService.getMessages(conversationId, token);
      setMessages(data);

      // Marquer comme lu
      await chatService.markAsRead(conversationId, token);
    } catch (error) {
      console.error('Erreur chargement messages:', error);
    }
  };

  const handleSelectConversation = async (conversation) => {
    setSelectedConversation(conversation);
    await loadMessages(conversation.id);
  };

  const handleSendMessage = async (messageText) => {
    if (!selectedConversation) return;

    try {
      const token = localStorage.getItem('token');
      await chatService.sendMessage(
        selectedConversation.id,
        { message_text: messageText, message_type: 'text' },
        token
      );

      // Recharger les messages
      await loadMessages(selectedConversation.id);
      // Recharger les conversations pour mettre à jour le dernier message
      await loadConversations();
    } catch (error) {
      console.error('Erreur envoi message:', error);
      throw error;
    }
  };

  const filteredConversations = conversations.filter(conv =>
    conv.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    conv.first_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    conv.last_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    conv.last_message?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="h-full p-6 bg-gray-50 min-h-screen">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-gray-900">Messages</h1>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
          <input
            type="text"
            placeholder="Rechercher des conversations..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 w-64"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-12rem)]">
        <ConversationList
          conversations={filteredConversations}
          selectedConversation={selectedConversation}
          onSelectConversation={handleSelectConversation}
          loading={loading}
        />

        <ChatArea
          selectedConversation={selectedConversation}
          messages={messages}
          onSendMessage={handleSendMessage}
        />
      </div>
    </div>
  );
};

export default AdminMessages;
